sequence.script:
var Base64     = Java.type("java.util.Base64");
var JavaString = Java.type("java.lang.String");

function mediator(mc) {
    try {
        var authHeader = mc.getProperty("apim_auth_header");
        if (!authHeader) {
            mc.setProperty("empr_id_ok",    "false");
            mc.setProperty("empr_id_error", "Authorization header ausente post-validacion APIM");
            return true;
        }

        var token = authHeader.toString().trim().substring(7).trim();
        var parts = token.split("\\.");
        if (parts.length !== 3) {
            mc.setProperty("empr_id_ok",    "false");
            mc.setProperty("empr_id_error", "JWT malformado post-validacion (sin 3 partes)");
            return true;
        }

        var decoder     = Base64.getUrlDecoder();
        var payloadJson = new JavaString(decoder.decode(parts[1]), "UTF-8");
        var payload     = JSON.parse(payloadJson);

        if (!payload.empr_id && payload.empr_id !== 0) {
            mc.setProperty("empr_id_ok",    "false");
            mc.setProperty("empr_id_error", "Claim empr_id ausente en JWT validado");
            return true;
        }

        mc.setProperty("empr_id_ok",   "true");
        mc.setProperty("apim_empr_id", payload.empr_id.toString());

    } catch (e) {
        mc.setProperty("empr_id_ok",    "false");
        mc.setProperty("empr_id_error", "Excepcion al extraer empr_id: " + e.message);
    }
    return true;
}
